	/**
	 * 
	 */
	private static final long serialVersionUID = 8325569111746288646L;
	private static PrintService impressora;
	private static String printMessage = "";
	
	public void paint(Graphics g) // chamando paint
	{
		g.drawString("Hardness Sistemas - Applet Java",5,10);
		//g.drawString("-> " + String.valueOf(Bematech.LeituraX()),5,30);
	}
	
	public void init() {

	}
	
	// Retorna a lista das impressoras disponíveis
	public String listarImpressoras() {
		String retorno = "";
		try {
			DocFlavor df = DocFlavor.SERVICE_FORMATTED.PRINTABLE;
			PrintService[] ps = PrintServiceLookup.lookupPrintServices(df, null);
            for (PrintService p: ps) {
            	retorno = retorno.length() == 0 ? p.getName() : retorno + "\n" + p.getName();
            }
        } catch (Exception e) {
            retorno = e.getMessage();
        }
		return retorno;
	}
	
	// Seleciona uma impressora por nome
	public boolean detectaImpressoras(String imp) {
        try {    
        	DocFlavor df = DocFlavor.SERVICE_FORMATTED.PRINTABLE;    
        	PrintService[] ps = PrintServiceLookup.lookupPrintServices(df, null);
        	boolean achou = false;
        	for (PrintService p: ps) {    
        		System.out.println("Impressora encontrada: " + p.getName());    
        		if (p.getName().contains(imp))  {
        			achou = true;
        			impressora = p;    
        			break;
                }
            }
            if (!achou) {
            	printMessage = "Impressora não encontrada!\nPor favor, verifique se ela está configurada e conectada.";
            	return false;
            } else {
            	return true;
            }
        } catch (Exception e) {
        	e.printStackTrace();
        	printMessage = "Ocorreu um erro:\n" + e.getMessage();
        	return false;
        }
    }
	
